function CircuitForgePure(){
  var DEFAULTS = {
    slidingWindowType: 'COUNT_BASED',
    slidingWindowSize: 10,
    minimumNumberOfCalls: 10,
    failureRateThreshold: 50,
    slowCallRateThreshold: 100,
    slowCallDurationThresholdMs: 1000,
    waitDurationInOpenStateMs: 1000,
    permittedNumberOfCallsInHalfOpenState: 4,
    callIntervalMs: 100,
    automaticTransitionFromOpenToHalfOpen: true
  };

  var NUM_KEYS = ['slidingWindowSize','minimumNumberOfCalls','failureRateThreshold',
                  'slowCallRateThreshold','slowCallDurationThresholdMs','waitDurationInOpenStateMs',
                  'permittedNumberOfCallsInHalfOpenState','callIntervalMs'];

  // 主流框架默认值对照（用于 UI 提示，不参与计算）
  var PRESETS = {
    resilience4j: {label:'Resilience4j 默认', slidingWindowType:'COUNT_BASED', slidingWindowSize:100,
      minimumNumberOfCalls:100, failureRateThreshold:50, slowCallRateThreshold:100,
      slowCallDurationThresholdMs:60000, waitDurationInOpenStateMs:60000,
      permittedNumberOfCallsInHalfOpenState:10},
    hystrix: {label:'Hystrix 默认', slidingWindowType:'TIME_BASED', slidingWindowSize:10,
      minimumNumberOfCalls:20, failureRateThreshold:50, slowCallRateThreshold:100,
      slowCallDurationThresholdMs:1000, waitDurationInOpenStateMs:5000,
      permittedNumberOfCallsInHalfOpenState:1},
    polly: {label:'Polly v8 默认', slidingWindowType:'TIME_BASED', slidingWindowSize:30,
      minimumNumberOfCalls:100, failureRateThreshold:10, slowCallRateThreshold:100,
      slowCallDurationThresholdMs:30000, waitDurationInOpenStateMs:5000,
      permittedNumberOfCallsInHalfOpenState:1},
    sentinel: {label:'Sentinel 慢调用比例', slidingWindowType:'TIME_BASED', slidingWindowSize:10,
      minimumNumberOfCalls:5, failureRateThreshold:100, slowCallRateThreshold:50,
      slowCallDurationThresholdMs:500, waitDurationInOpenStateMs:10000,
      permittedNumberOfCallsInHalfOpenState:1}
  };

  function clone(o){ var r = {}, k; for (k in o) if (Object.prototype.hasOwnProperty.call(o, k)) r[k] = o[k]; return r; }

  function parseConfig(text){
    var cfg = clone(DEFAULTS), unknown = [], bad = [];
    var lines = String(text == null ? '' : text).replace(/\r\n/g, '\n').split('\n');
    for (var i = 0; i < lines.length; i++){
      var ln = lines[i];
      var hash = ln.indexOf('#'); if (hash >= 0) ln = ln.slice(0, hash);
      ln = ln.trim();
      if (ln === '') continue;
      var sep = ln.indexOf('='); if (sep < 0) sep = ln.indexOf(':');
      if (sep < 0){ bad.push('第 ' + (i+1) + ' 行不是 key=value：' + ln); continue; }
      var k = ln.slice(0, sep).trim(), v = ln.slice(sep+1).trim();
      if (!Object.prototype.hasOwnProperty.call(DEFAULTS, k)){ unknown.push(k); continue; }
      if (k === 'slidingWindowType'){
        var up = v.toUpperCase();
        if (up !== 'COUNT_BASED' && up !== 'TIME_BASED'){ bad.push('slidingWindowType 只能是 COUNT_BASED / TIME_BASED'); continue; }
        cfg[k] = up; continue;
      }
      if (k === 'automaticTransitionFromOpenToHalfOpen'){ cfg[k] = /^(true|yes|1|on)$/i.test(v); continue; }
      var n = Number(v);
      if (!isFinite(n)){ bad.push(k + ' 不是合法数字：' + v); continue; }
      cfg[k] = n;
    }
    return {error:null, cfg:cfg, unknown:unknown, bad:bad};
  }

  function lintConfig(cfg){
    var out = [];
    function add(level, text){ out.push({level:level, text:text}); }
    if (cfg.failureRateThreshold <= 0 || cfg.failureRateThreshold > 100)
      add('err', 'failureRateThreshold 必须落在 (0, 100]，当前 ' + cfg.failureRateThreshold);
    if (cfg.slowCallRateThreshold <= 0 || cfg.slowCallRateThreshold > 100)
      add('err', 'slowCallRateThreshold 必须落在 (0, 100]，当前 ' + cfg.slowCallRateThreshold);
    if (cfg.slidingWindowType === 'COUNT_BASED' && cfg.minimumNumberOfCalls > cfg.slidingWindowSize)
      add('err', 'minimumNumberOfCalls(' + cfg.minimumNumberOfCalls + ') 大于 COUNT_BASED 窗口容量(' +
                 cfg.slidingWindowSize + ')，样本数永远凑不齐，熔断器不会触发');
    if (cfg.permittedNumberOfCallsInHalfOpenState <= 0)
      add('err', '半开放行数必须大于 0，否则熔断后永远无法恢复');
    if (cfg.minimumNumberOfCalls < 5)
      add('warn', 'minimumNumberOfCalls 仅 ' + cfg.minimumNumberOfCalls + '，样本过小，单次抖动即可触发误熔断');
    if (cfg.waitDurationInOpenStateMs < 1000)
      add('warn', 'waitDurationInOpenStateMs 仅 ' + cfg.waitDurationInOpenStateMs + 'ms，恢复过快会反复冲击尚未恢复的下游');
    if (cfg.failureRateThreshold >= 100)
      add('warn', 'failureRateThreshold = 100，只有窗口内全部失败才熔断，几乎等于关闭保护');
    if (cfg.permittedNumberOfCallsInHalfOpenState > cfg.slidingWindowSize)
      add('warn', '半开放行数大于窗口容量，半开判定样本会超过正常窗口规模');
    if (!cfg.automaticTransitionFromOpenToHalfOpen)
      add('info', '未开启自动转半开：必须有新请求到达才会尝试探活，低流量场景可能长期停在 OPEN');
    if (cfg.slowCallRateThreshold < 100 && cfg.slowCallDurationThresholdMs <= 0)
      add('err', '启用了慢调用熔断，但 slowCallDurationThresholdMs <= 0');
    if (out.length === 0) add('ok', '配置体检通过，未发现明显问题');
    return out;
  }

  // 事件语法：S / F / S:120 / F:1500 / T（超时=失败且慢）；支持 xN 或 *N 重复
  function parseEvents(text){
    var s = String(text == null ? '' : text).trim();
    if (s === '') return {error:'请输入调用事件序列，例如：F x10 S x5'};
    var toks = s.split(/[\s,]+/).filter(function(x){ return x !== ''; });
    var out = [], i;
    for (i = 0; i < toks.length; i++){
      var t = toks[i];
      var rep = 1;
      var mrep = /^[xX*](\d+)$/.exec(t);
      if (mrep){
        if (!out.length) return {error:'重复标记 ' + t + ' 前面没有事件'};
        var last = out[out.length - 1], n = parseInt(mrep[1], 10);
        if (n < 1 || n > 5000) return {error:'重复次数需在 1..5000：' + t};
        for (var r = 1; r < n; r++) out.push({ok:last.ok, durationMs:last.durationMs});
        continue;
      }
      var m = /^([SsFfTt])(?::(\d+))?(?:[xX*](\d+))?$/.exec(t);
      if (!m) return {error:'无法识别的事件：' + t + '（应为 S / F / T / S:120 / F x10）'};
      var kind = m[1].toUpperCase();
      var dur = m[2] === undefined ? 0 : parseInt(m[2], 10);
      if (m[3] !== undefined) rep = parseInt(m[3], 10);
      if (rep < 1 || rep > 5000) return {error:'重复次数需在 1..5000：' + t};
      for (var j = 0; j < rep; j++){
        if (kind === 'T') out.push({ok:false, durationMs:Math.max(dur, 1e9)});
        else out.push({ok:(kind === 'S'), durationMs:dur});
      }
    }
    if (out.length > 20000) return {error:'事件数量过多（上限 20000）'};
    return {error:null, events:out};
  }

  function rate(list, pick){
    if (!list.length) return 0;
    var n = 0;
    for (var i = 0; i < list.length; i++) if (pick(list[i])) n++;
    return n * 100 / list.length;
  }

  function simulate(cfg, events){
    if (!events || !events.length) return {error:'事件序列为空'};
    var state = 'CLOSED', win = [], half = [], openedAt = -1;
    var timeline = [], transitions = [];
    var permitted = 0, rejected = 0, failures = 0, slowTotal = 0;

    function trip(t, from, reason){
      state = 'OPEN'; openedAt = t; win = []; half = [];
      transitions.push({at:t, from:from, to:'OPEN', reason:reason});
    }

    for (var i = 0; i < events.length; i++){
      var ev = events[i], t = i * cfg.callIntervalMs;

      if (state === 'OPEN'){
        if (t - openedAt >= cfg.waitDurationInOpenStateMs){
          state = 'HALF_OPEN'; half = [];
          transitions.push({at:t, from:'OPEN', to:'HALF_OPEN', reason:'熔断等待期结束，开始探活'});
        } else {
          rejected++;
          timeline.push({i:i, at:t, state:'OPEN', outcome:'NOT_PERMITTED', failureRate:100, slowRate:0});
          continue;
        }
      }

      var slow = cfg.slowCallRateThreshold < 100 && ev.durationMs >= cfg.slowCallDurationThresholdMs;
      var call = {ok:ev.ok, slow:slow, t:t};
      permitted++;
      if (!ev.ok) failures++;
      if (slow) slowTotal++;

      if (state === 'HALF_OPEN'){
        half.push(call);
        var hf = rate(half, function(c){ return !c.ok; });
        var hs = rate(half, function(c){ return c.slow; });
        timeline.push({i:i, at:t, state:'HALF_OPEN', outcome:(ev.ok ? 'SUCCESS' : 'FAILURE'),
                       failureRate:hf, slowRate:hs});
        if (half.length >= cfg.permittedNumberOfCallsInHalfOpenState){
          if (hf >= cfg.failureRateThreshold) trip(t, 'HALF_OPEN', '探活失败率 ' + hf.toFixed(1) + '% ≥ 阈值');
          else if (hs >= cfg.slowCallRateThreshold) trip(t, 'HALF_OPEN', '探活慢调用率 ' + hs.toFixed(1) + '% ≥ 阈值');
          else {
            state = 'CLOSED'; win = []; half = [];
            transitions.push({at:t, from:'HALF_OPEN', to:'CLOSED', reason:'探活通过，恢复正常'});
          }
        }
        continue;
      }

      win.push(call);
      if (cfg.slidingWindowType === 'COUNT_BASED'){
        while (win.length > cfg.slidingWindowSize) win.shift();
      } else {
        var cut = t - cfg.slidingWindowSize * 1000;
        while (win.length && win[0].t < cut) win.shift();
      }
      var fr = rate(win, function(c){ return !c.ok; });
      var sr = rate(win, function(c){ return c.slow; });
      timeline.push({i:i, at:t, state:'CLOSED', outcome:(ev.ok ? 'SUCCESS' : 'FAILURE'),
                     failureRate:fr, slowRate:sr});
      if (win.length >= cfg.minimumNumberOfCalls){
        if (fr >= cfg.failureRateThreshold) trip(t, 'CLOSED', '失败率 ' + fr.toFixed(1) + '% ≥ 阈值 ' + cfg.failureRateThreshold + '%');
        else if (sr >= cfg.slowCallRateThreshold) trip(t, 'CLOSED', '慢调用率 ' + sr.toFixed(1) + '% ≥ 阈值 ' + cfg.slowCallRateThreshold + '%');
      }
    }

    var opens = 0;
    for (var k = 0; k < transitions.length; k++) if (transitions[k].to === 'OPEN') opens++;
    return {
      error:null, timeline:timeline, transitions:transitions,
      summary:{
        total:events.length, permitted:permitted, rejected:rejected,
        failures:failures, slowCalls:slowTotal, openCount:opens,
        finalState:state,
        shedRate: events.length ? (rejected * 100 / events.length) : 0,
        observedFailureRate: permitted ? (failures * 100 / permitted) : 0
      }
    };
  }

  function recovery(cfg){
    var permittedCalls = cfg.permittedNumberOfCallsInHalfOpenState;
    var allowedFailures = Math.ceil(permittedCalls * cfg.failureRateThreshold / 100) - 1;
    if (allowedFailures < 0) allowedFailures = 0;
    var minSuccesses = permittedCalls - allowedFailures;
    if (minSuccesses < 0) minSuccesses = 0;
    return {
      waitMs: cfg.waitDurationInOpenStateMs,
      probeCalls: permittedCalls,
      allowedFailuresInProbe: allowedFailures,
      minSuccessesToClose: minSuccesses,
      fastestRecoveryMs: cfg.waitDurationInOpenStateMs + permittedCalls * cfg.callIntervalMs,
      callsToTrip: Math.max(cfg.minimumNumberOfCalls,
                            Math.ceil(cfg.minimumNumberOfCalls * cfg.failureRateThreshold / 100))
    };
  }

  function analyze(cfgText, eventText){
    var pc = parseConfig(cfgText);
    if (pc.error) return {error:pc.error};
    var pe = parseEvents(eventText);
    if (pe.error) return {error:pe.error};
    var sim = simulate(pc.cfg, pe.events);
    if (sim.error) return {error:sim.error};
    return {
      error:null, cfg:pc.cfg, unknown:pc.unknown, bad:pc.bad,
      lint:lintConfig(pc.cfg), recovery:recovery(pc.cfg),
      timeline:sim.timeline, transitions:sim.transitions, summary:sim.summary
    };
  }

  var api = {DEFAULTS:DEFAULTS, PRESETS:PRESETS, parseConfig:parseConfig, lintConfig:lintConfig,
             parseEvents:parseEvents, simulate:simulate, recovery:recovery, analyze:analyze};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {CircuitForgePure:CircuitForgePure}; }
  return api;
}
